package com.theboss.utils;

/**
 * Shared, cross-test holder for values produced in one test and consumed in
 * another (e.g. an email generated during sign-up and reused during login).
 */
public final class TestContext {

    private static volatile String signupEmail;

    private TestContext() {}

    /**
     * Stores the email address generated by the sign-up flow so other tests can
     * reuse it (e.g. a subsequent login).
     *
     * @param email the email captured during sign-up
     */
    public static void setSignupEmail(String email) {
        signupEmail = email;
    }

    /**
     * Returns the email previously saved by {@link #setSignupEmail(String)},
     * or {@code null} if no sign-up has run in this JVM.
     *
     * @return the stored sign-up email, or {@code null} if none
     */
    public static String getSignupEmail() {
        return signupEmail;
    }
}
